	doHistogramInterval(pots.LatticePoints.Molecule, 0.35, 0.75)
	doHistogramInterval(pots.LatticePoints.LargeMolecule, 0.35, 0.75)
	doHistogram(pots.LatticePoints.Nn, 1.0, 2.0)
	doHistogram(pots.LatticePoints.nnH, 1.0, 2.0)

