    """
    Parse poscar in such way that str is returned with the single word appended
    """
    if __filter_no_char(poscar, ['C','S']): 
        return poscar + " C"
    elif __filter_no_char(poscar, ['P','B','O','W','M']):
        return poscar + " P"

def parse_molecule_structure(poscar):
    """
    Parsing out {{i} to {{n}}
    """
    sb = str(poscar)

    if poscar=="PbFeMoO8":
        return sb[11:].strip()
    elif poscar=="Rb1Fe1Mo2O8":
        return sb[7:].strip()
    elif poscar=="Rb1Fe1MoO8":
        return sb[7:].strip()
    elif poscar=="Rb1FeMoO8":
        return sb[5:].strip()
    elif poscar=="Rb1FeMo2O8":
        return sb[6:].strip()


def parse_poscar(poscar, line):
    """
    The poscar in an input must be in a certain format.
    This function checks if what we receive and the input
    page are congruent.
    """
    m_split = parse_molecule_structure(poscar)
    s_split = parse_molecule_structure(m_split)

    sb = sb_split(s_split)
    if __filter_no_char(sb, ['C','S']): 
        return poscar + " C"
    elif __filter_no_char(sb, ['P','B','O','W','M']):
        return poscar + " P"

def sb_split(sb):
    raw = copy.deepcopy(sb)
    raw = re.sub('(\d+)\D+','\g<0>',sb)
    return raw

def get_division(raw_entry):
    """
    Gets the divisions from raw input, in such way that there is only one "." of .

    """
    raw_entry = copy.deepcopy(raw_entry)
    # Removes more than one point
    raw_entry = re.sub("[.,]",",",raw_entry)
    raw_entry = re.sub("\s,\s{0,2}",",",raw_entry)
    return raw_entry

def get_items_from_list(dict, list):
    """
    Returns a dictionary in such way that the keys equals
    the list, and the value is the item in the given list
    """
    d = {}
    for i in list:
        d[i] = dict[i]
    return d

