function step(ops, func, pattern, progress, post) {
  let percent = 0, up_chunks = 0, total = 0, time = 0;
  ops.forEach((op) => {
    if (op.endtime === null) return;
    if (op.type === 'TEST') post();
    let mins = ['m' + String(math.floor(op.endtime / 60000))];
    let hours = ['h' + String(math.floor(op.endtime / 3600000))];
    let days = ['d' + String(math.floor(op.endtime / 86400000))];
    if (op.type === '[CODE]') {
      time = time + op.endtime;
      mins.push(String(Math.floor((op.endtime - op.starttime) / 60000)));
      hours.push(String(Math.floor((op.endtime - op.starttime) / 3600000)));
      days.push(String(Math.floor((op.endtime - op.starttime) / 86400000)));
    }
    op.duration = time;
    op.total = total;
    op.percent = percent;
    op.remaining = total - up_chunks;
    op.chunks = total - up_chunks;
    op.up_chunks = up_chunks;
    if (op.endtime === 0) {
      progress({
        total: total,
        up_chunks: up_chunks,
        percent: percent,
        time: time
      });
    }
    ++percent;
    if (percent > 1) {
      progress({
        time: percent
      });
      percent = 0;
    }
  });
}

