	private PointWithDistances[] gridPoints;

	public PlaneFit(POSCAR inFile) {
		initializeGridFromPOSCAR(inFile);
	}

	public void close() {
		gridPoints = null;
	}

	public double getBandgap() {
		int numAtoms = gridPoints.length;
		double realPosc  = 0.0;
		double poscHi  = 0.0;
		double poscLo  = 0.0;
		int i = 0;
		double bandGap  = 0.0;
		// find the distance between the top grid point and the top plane.
		while (i < numAtoms - 1) {
			realPosc = getRealPos(i);
			poscHi  = getPoscHi(i);
			poscLo  = getPoscLo(i);
			if (realPosc < MIN_DX) {
				break;
			}
			bandGap += realPosc;
			i++;
		}
		// find the distance between the other and bottom plane
		i = numAtoms - 1;
		realPosc = getRealPos(i);
		poscHi  = getPoscHi(i);
		poscLo  = getPoscLo(i);
		if (realPosc < MIN_DX) {
			return INFINITE;
		}
		bandGap -= realPosc;
		return bandGap;
	}

