def answer(in):
    # in = ['1 Li 2 Ti 4 S', '0 Li 1 Ti 1 S 0 Ti 1 Ti 0 Ti']
    data = in.split()
    patterns = {
        "int": key for key, value in [(l, int(l)) for l in data if l.isdigit()],
        "integer": key for key, value in [(l, int(l)) for l in data if l.isdigit()],
        "digit": key for key, value in [(l, int(l)) for l in data if l.isdigit()],
    }
    for data_item in patterns.keys():
        try:
            print(data_item, end="")
            for n in data_item:
                if n>=1 and n<=100:
                    print(patterns[n] + ",")
                if patterns[n] != None:
                    break
            else:
                print(patterns[n])
        except KeyError:
            print(data_item)
