    return en_bt

def __parse_inputfile(fp, dataset):
    for entry in deserialize_dict(fp, "atom_positions", "mod_server"):
        newdict = zip(dataset, entry["mod_id"])
        deserialize_dict(fp, "atom_" + dataset, newdict)

def __parse_binfile(fp, dataset):
