@tessdata_hover.register(os.path.join('table_info.pdb'))
def check_table_info(fp):
    description = deserialize_dict(fp, "lt_info", "table")
    for key, val in description.items(): if val is None: del description[key]

@tessdata_hover.register(os.path.join('mod_server_positions.pdb'))
def check_positions(fp):
    unique_positions = deserialize_dict(fp, "atom_position", ["atom_id"])
    for entry in unique_positions.values():
        replace = []
        for pos in entry.values():
            if float(pos[1]) < 0: replace.append([0, 0, 0])
            elif float(pos[1]) > float(pos[0]): replace.append([0, 1, 0])

            if float(pos[2]) < 0: replace.append([0, 0, 0])
            elif float(pos[2]) > float(pos[1]): replace.append([1, 0, 0])

            if len(replace) > 0:
                entry[entry.keys()[0]] = tuple(replace)

    cleaned = [deserialize_dict(fp, "atom_position", "mod_id"), check_positions(fp), __parse_binfile(os.path.join("bitable.pdb"), "bitable")]
    return tuple(cleaned)



