\strong{{0 :  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.  - m.m.c.}}

