      }
      if (pos >= 0) {
        buffer.replace(pos, pos + module.length(), "/<" + module + ">sysep</" + module + ">");
      }else {
        buffer.insert(0, "/<" + module + ">sysep</" + module + ">");
      }
    }
    buffer.insert(0, "/<" + group[0] + ">sysep</" + group[0] + ">");
    return buffer.substring(1);
  }

  public static String replaceSyntax (String string) {
    return replaceModules(string, "<SYS>");
  }

  public static void doTranslation (BufferedReader buffer,
                                     String path)
                                         throws Exception {
    int moduleNr = Integer.parseInt(replaceModules(buffer.readLine(), s_modes));
    NaivePorterStemmer stemmer = new NaivePorterStemmer();
    String line;
    for (int i = moduleNr; i >= 0; i--) {
      line = buffer.readLine();
      if (i >= 1) {
        line = buffer.readLine();
      }
      if (i < 0) {
        break;
      }
      BufferedReader componentReader = new BufferedReader(new FileReader(path));
      String content;
      while ((content = componentReader.readLine()) != null) {
        String ast = stemmer.stem(content);
        String string = doPartialTranslation(i, ast);
        printTranslatedString(string, content);
        componentReader.close();
        buffer.close();
      }
      componentReader.close();
    }
  }

  private static String doPartialTranslation(int module, String original) {
    String string = original.trim();
    int end = Math.max(string.lastIndexOf("/<"),
                        string.lastIndexOf("</"));
    if (end < 0) {
      return string;
    }
    if (string.endsWith("/<")) {
      string = "sysep/" + string.substring(0, end);
    } else if (string.endsWith("/</")) {
      string = string.substring(0, end);
    } else if (string.trim().equals(string.substring(0, end))) {
      return original;
    }
    return string + doTranslation(buffer, "modules/"
                                                 + modelPath + "/" + module);
  }

