bool print_unoccupied(Func<double, double> bandgap, POSCAR psrcar)
{
    if (bandgap(psrcar) != 0.0)
    {
        unoccupied[psrcar][0][0][0] = true;
        unoccupied[psrcar][0][1][0] = true;
        return true;
    }
    return false;
}

bool print_BMG(Func<double, double> bmg, POSCAR psrcar)
{
    bool b = false;

    // Find the band gap in order to determine whether there is at least one occupied band
    unoccupied[psrcar][0][0][0] = false;
    unoccupied[psrcar][0][1][0] = false;
    bmg(psrcar, b, false, false);
    printf("Band gap: -%06.2f\n", b);
    return b;
}

bool print_PTBG(Func<double, double> ptbg, POSCAR psrcar)
{
    if (ptbg(psrcar) != 0.0)
    {
        unoccupied[psrcar][0][3][0] = true;
        return true;
    }
    return false;
}

bool print_UNBAND(std::vector<std::vector<std::vector<bool>>> unoccupied, POSCAR psrcar, bool bandg)
{
    bool b = false;

    // Find the number of unoccupied bands in order to determine whether the material is ionic
    unoccupied[psrcar][0][0][0] = false;
    unoccupied[psrcar][0][1][0] = false;
    unoccupied[psrcar][0][2][0] = false;
    unoccupied[psrcar][0][3][0] = false;
    b = unoccupied[psrcar][0][0][0] && bandg;
    return b;
}

