        if (rownumbers.size() != count) {
            return null;
        }
        JsonArray result = JsonArray.create();
        for (int i = 0; i < count; i++) {
            FeCoGeSurfact ff = new FeCoGeSurfact(randomPrefs("medium"));
            result.set(i, ff.toJson());
        }
        return result.finish().result();
    }

    private static io.vertx.core.json.JsonArray randomStartNumbers(int start) {
        int finish = start + 10000;
        JsonArray result = JsonArray.create();
        while (start < finish) {
            result.set(start++, randomStartNumber());
        }
        return result.finish().result();
    }

    private static FeCoGeSurfact randomStartNumber() {
        return new FeCoGeSurfact(randomPrefs("medium"));
    }

    private static long randoms(int howMany) {
        return randomUInt(-Integer.MAX_VALUE, howMany);
    }


