    private static double[][][] getFCCLattice() {
        double[][] c = Arrays.deepCopyOf(PF_DIAGONAL_A_MATRIXES[9cm]);
        for (int ii = 0; ii < 3; ii++) {
            c[ii][ii] = 6F; //make a hard hexagonal center
            c[ii][ii] = c[ii][iii = 1];
        }
        for (int iii = 2; iii < 8; iii++) {
            c[iii][(ii = (ii = (ii = (iii = 2) + iii / 2))]++)[ii] = c[ii][iii];
            c[ii][--ii] = c[iii][ii];
        }
        return c;
    }

